/**
 * @file urlParser.js
 * @description Utilities for parsing and validating table access URL parameters from QR codes.
 *
 * BUG-07 FIX: The previous implementation required ?table=X&status=active in the URL params.
 * Modern QR codes generated by the backend use the format ?table=X&token=Y (a secure token).
 * This rewrite drops the legacy `status` check and instead reads `token`, making the landing
 * page and ordering flow work with all physical QR codes in production.
 */

/**
 * Parse table-related URL search parameters.
 * Expected format: ?table=3&token=<qrToken>
 *
 * @param {string} searchString - e.g. "?table=3&token=abc123"
 * @returns {{ table: string|null, token: string|null }}
 */
export function parseTableParams(searchString) {
  const params = new URLSearchParams(searchString);
  return {
    table: params.get('table'),
    token: params.get('token'),
  };
}

/**
 * Validate that the table access parameters are correct.
 * - `table` must exist and be a positive integer
 *
 * Note: `token` is passed through to the ordering page for QR validation
 * via the /api/tables/validate-qr endpoint — it is NOT validated here to
 * keep this utility pure and avoid async calls in URL parsing.
 *
 * @param {{ table: string|null, token: string|null }} params
 * @returns {{ valid: boolean, error?: string, tableNumber?: number, token?: string|null }}
 */
export function isValidTableAccess(params) {
  if (!params.table) {
    return {
      valid: false,
      error: 'No table number found. Please scan the QR code at your table to place an order.',
    };
  }

  const tableNum = parseInt(params.table, 10);
  if (isNaN(tableNum) || tableNum <= 0) {
    return {
      valid: false,
      error: 'Invalid table number. Please scan a valid QR code.',
    };
  }

  return {
    valid: true,
    tableNumber: tableNum,
    token: params.token ?? null,
  };
}
